//! Synthetic scene: end-to-end geometric validation of the stitcher.
//!
//! Principle: the test frames are generated by an **independently written
//! inverse projection** (pixel → camera ray → world → (lon, lat) →
//! scene) — we do not reuse the stitcher's forward path. The render is
//! then compared with the analytic scene: any convention, warp,
//! sampling or blend error degrades the gradient channels.
//!
//! The scene is 360°-periodic in longitude: the ring closing seam
//! (column 0 vs column W−1) is directly testable.

use pnex_stitcher::{stitch, Frame, Params, Pipeline, QualityParams};

/// Multi-octave textured scene (WHOLE cycles in longitude → guaranteed 360°
/// periodicity, unlike hashed noise), seeded amplitudes.
/// Sum of amplitudes 0.92 → values bounded to [77, 183]: under the JPEG q90
/// noise and contrasted enough for NCC alignment. The gradient scene
/// [`scene`] is still used by the Legacy regressions.
///
/// (cycles_lon, cycles_lat, amplitude, phase_lon, phase_lat) per octave.
const OCTAVES: [(i32, i32, f32, f32, f32); 4] = [
    (3, 2, 0.30, 0.7, 1.3),
    (7, 5, 0.25, 2.1, 0.4),
    (13, 9, 0.22, 4.7, 2.9),
    (23, 17, 0.15, 1.8, 5.2),
];

fn texture_channel(lon: f32, lat: f32, phase: f32) -> f32 {
    let (lo, la) = (lon.to_radians(), lat.to_radians());
    let mut v = 0.0f32;
    for &(cy, cx, amp, p, q) in &OCTAVES {
        v += amp * ((cy as f32 * lo + p + phase).sin() * (cx as f32 * la + q).sin());
    }
    128.0 + 55.0 * v.clamp(-0.92, 0.92)
}

/// Textured scene: 3 phase-shifted channels (useful for per-channel gains) on the
/// same octave texture. Optional obstacle: dark vertical pillar on
/// `lon ∈ [18°, 22°]` (seam test).
fn scene_texture(lon_deg: f32, lat_deg: f32, obstacle: bool) -> [u8; 3] {
    if obstacle && (18.0..22.0).contains(&lon_deg) {
        return [10, 10, 10];
    }
    [
        texture_channel(lon_deg, lat_deg, 0.0) as u8,
        texture_channel(lon_deg, lat_deg, 0.9) as u8,
        texture_channel(lon_deg, lat_deg, 1.7) as u8,
    ]
}

/// Scene: R = smooth gradient in longitude, G = smooth gradient in latitude,
/// B constant. Amplitude 100: steep enough to detect a displaced
/// frame (100·(π/180) ≈ 1.7 levels per degree), gentle enough to stay
/// under the JPEG q85 noise. No contrasted checkerboard: at 512 px output it
/// falls below the DCT block size and JPEG would bleed its
/// contrast into the compared R/G channels.
fn scene(lon_deg: f32, lat_deg: f32) -> [u8; 3] {
    let (lo, la) = (lon_deg.to_radians(), lat_deg.to_radians());
    let r = (128.0 + 100.0 * lo.sin()).round().clamp(0.0, 255.0) as u8;
    let g = (128.0 + 100.0 * la.sin()).round().clamp(0.0, 255.0) as u8;
    [r, g, 90]
}

/// Frame generation by INDEPENDENT inverse projection: the camera axes
/// in the world are rebuilt from (yaw, pitch, roll) without
/// calling `euler_to_mat`, and each pixel is re-projected onto the sphere.
/// The scene is passed as a parameter (gradient [`scene`] for Legacy,
/// multi-octave texture [`scene_texture`] for Quality).
fn make_frame_with(
    yaw_deg: f32,
    pitch_deg: f32,
    roll_deg: f32,
    w: u32,
    h: u32,
    hfov_deg: f32,
    scene: impl Fn(f32, f32) -> [u8; 3],
) -> Frame {
    let (y, p, r) = (
        yaw_deg.to_radians(),
        pitch_deg.to_radians(),
        roll_deg.to_radians(),
    );
    let (sp, cp) = p.sin_cos();
    let (sy, cy) = y.sin_cos();
    let (sr, cr) = r.sin_cos();

    // Camera→world axes (see the stitcher's convention).
    let forward = [cp * cy, cp * sy, sp];
    let r_base = [sy, -cy, 0.0];
    let d_base = [
        forward[1] * r_base[2] - forward[2] * r_base[1],
        forward[2] * r_base[0] - forward[0] * r_base[2],
        forward[0] * r_base[1] - forward[1] * r_base[0],
    ];
    let right = [
        r_base[0] * cr + d_base[0] * sr,
        r_base[1] * cr + d_base[1] * sr,
        r_base[2] * cr + d_base[2] * sr,
    ];
    let down = [
        d_base[0] * cr - r_base[0] * sr,
        d_base[1] * cr - r_base[1] * sr,
        d_base[2] * cr - r_base[2] * sr,
    ];

    let f_px = (w as f32 * 0.5) / (hfov_deg * 0.5).to_radians().tan();
    let cx = w as f32 * 0.5;
    let cy = h as f32 * 0.5;

    let mut rgb = vec![0u8; (w * h * 3) as usize];
    for j in 0..h {
        for i in 0..w {
            // Camera ray (not normalised, pure direction) → world.
            let a = (i as f32 + 0.5 - cx) / f_px;
            let b = (j as f32 + 0.5 - cy) / f_px;
            let cam = [a, b, 1.0];
            let world = [
                right[0] * cam[0] + down[0] * cam[1] + forward[0] * cam[2],
                right[1] * cam[0] + down[1] * cam[1] + forward[1] * cam[2],
                right[2] * cam[0] + down[2] * cam[1] + forward[2] * cam[2],
            ];
            let lon = world[1].atan2(world[0]).to_degrees();
            // asin requires a UNIT vector (norm √(1+a²+b²) > 1 towards the
            // frame edges) — without normalisation, lat is overestimated.
            let n = (world[0] * world[0] + world[1] * world[1] + world[2] * world[2]).sqrt();
            let lat = (world[2] / n).asin().to_degrees();
            let [r, g, b2] = scene(lon, lat);
            let o = ((j * w + i) * 3) as usize;
            rgb[o] = r;
            rgb[o + 1] = g;
            rgb[o + 2] = b2;
        }
    }

    Frame {
        rgb,
        width: w,
        height: h,
        yaw_deg,
        pitch_deg,
        roll_deg,
    }
}

/// Frame on the gradient scene (Legacy regressions).
fn make_frame(yaw_deg: f32, pitch_deg: f32, roll_deg: f32, w: u32, h: u32, hfov_deg: f32) -> Frame {
    make_frame_with(yaw_deg, pitch_deg, roll_deg, w, h, hfov_deg, scene)
}

/// Deterministic LCG for pose jitter (reproducible test, zero deps).
struct Lcg(u64);

impl Lcg {
    fn next_f32(&mut self, lo: f32, hi: f32) -> f32 {
        self.0 = self
            .0
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let u = (self.0 >> 33) as f32 / (1u64 << 31) as f32; // [0, 1)
        lo + u * (hi - lo)
    }
}

/// Output grid: (lon, lat) of the centre of pixel (i, j) — mirror of the
/// render conventions, rewritten here to stay independent.
fn out_lonlat(i: u32, j: u32, w: u32, h: u32) -> (f32, f32) {
    (
        180.0 - (i as f32 + 0.5) * 360.0 / w as f32,
        90.0 - (j as f32 + 0.5) * 180.0 / h as f32,
    )
}

/// Ring 16 × hfov 65° at pitch 15° (the real capture): gradients
/// reproduced to ±3, continuous closing seam, poles filled.
#[test]
fn anneau_16_reprojection_et_poles() {
    let (fw, fh, hfov) = (100u32, 75u32, 65.0_f32);
    let pitch = 15.0_f32;
    let frames: Vec<Frame> = (0..16)
        .map(|k| make_frame(k as f32 * 22.5, pitch, 0.0, fw, fh, hfov))
        .collect();

    let params = Params {
        hfov_deg: hfov,
        out_width: 512,
        min_band_coverage: 0.98,
        ..Params::default()
    };
    let out = stitch(&frames, &params).unwrap();
    assert_eq!(out.width, 512);
    assert_eq!(out.height, 256);
    // ~0.99 expected: the partial rows at the band edges cost
    // ~1 % (the hole of a missing frame would cost ~11 % → refusal).
    assert!(
        out.band_coverage >= 0.98,
        "coverage = {}",
        out.band_coverage
    );

    // Decodes the rendered panorama (before GPano the JPEG is re-encodable).
    let (rgb, w, h) = pnex_stitcher::decode_jpeg_rgb(&out.jpeg).unwrap();
    assert_eq!((w, h), (512, 256));

    // 1) Reprojection: gradients R (lon) and G (lat) to ±4 within the covered
    //    band, inset by 1° at the edges (unavoidable azimuthal holes
    //    within ~0.4° below the exact edge in rectilinear — see corner);
    //    poles excluded; ±4 = render ≈ ±1 + JPEG q85 ≈ ±3.
    let vfov_half = (fh as f32 * 0.5 / (fw as f32 * 0.5 / (hfov * 0.5).to_radians().tan()))
        .atan()
        .to_degrees();
    let lat_top = pitch + vfov_half - 1.0;
    let lat_bot = pitch - vfov_half + 1.0;
    for j in 0..h {
        for i in 0..w {
            let (lon, lat) = out_lonlat(i, j, w, h);
            if lat > lat_top || lat < lat_bot {
                continue;
            }
            let [r, g, _] = scene(lon, lat);
            let o = ((j * w + i) * 3) as usize;
            assert!(
                (rgb[o] as i32 - r as i32).abs() <= 5,
                "R ({i},{j}) lon {lon}: rendered {} expected {}",
                rgb[o],
                r
            );
            assert!(
                (rgb[o + 1] as i32 - g as i32).abs() <= 5,
                "G ({i},{j}) lat {lat}: rendered {} expected {}",
                rgb[o + 1],
                g
            );
        }
    }

    // 2) Dressed caps (gradient fill_poles): the pole converges towards the
    //    MEAN hue of the band edge (no more copy spreading, streaks
    //    and wavy join). The polar row is therefore horizontally plain,
    //    its mean matches that of the band edge (invariant along the
    //    gradient: blend of the constant `mean` and of the row `edge`), and
    //    the rows close to the pole stay nearly identical (JPEG ±6:
    //    8×8 DCT distribution + 4:2:0 chroma).
    let row_len = (w * 3) as usize;
    let bande_haute = ((90.0 - lat_top) / 180.0 * h as f32) as usize;
    let bande_basse = ((90.0 - lat_bot) / 180.0 * h as f32) as usize;
    let max_diff_rows = |rgb: &[u8], a: usize, b: usize| {
        rgb[a * row_len..(a + 1) * row_len]
            .iter()
            .zip(&rgb[b * row_len..(b + 1) * row_len])
            .map(|(x, y)| (*x as i32 - *y as i32).abs())
            .max()
            .unwrap_or(0)
    };
    let within_row_spread = |rgb: &[u8], j: usize| -> i32 {
        let row = &rgb[j * row_len..(j + 1) * row_len];
        let (mut min, mut max) = ([255i32; 3], [0i32; 3]);
        for px in row.as_chunks::<3>().0 {
            for (k, &v) in px.iter().enumerate() {
                min[k] = min[k].min(v as i32);
                max[k] = max[k].max(v as i32);
            }
        }
        (0..3).map(|k| max[k] - min[k]).max().unwrap()
    };
    let row_mean = |rgb: &[u8], j: usize| -> [f32; 3] {
        let row = &rgb[j * row_len..(j + 1) * row_len];
        let mut m = [0.0f32; 3];
        for px in row.as_chunks::<3>().0 {
            for (k, &v) in px.iter().enumerate() {
                m[k] += v as f32;
            }
        }
        let n = w as f32;
        [m[0] / n, m[1] / n, m[2] / n]
    };
    assert!(bande_haute > 5, "upper band too small: {bande_haute}");
    assert!(
        max_diff_rows(&rgb, 0, 3) <= 6,
        "north pole: rows 0 and 3 diverge ({})",
        max_diff_rows(&rgb, 0, 3)
    );
    assert!(
        within_row_spread(&rgb, 0) <= 6,
        "north pole: polar row not plain (spread {})",
        within_row_spread(&rgb, 0)
    );
    let (m0, me) = (row_mean(&rgb, 0), row_mean(&rgb, bande_haute - 2));
    for k in 0..3 {
        assert!(
            (m0[k] - me[k]).abs() <= 15.0,
            "north pole: polar mean {m0:?} ≠ edge hue {me:?}"
        );
    }
    assert!(
        max_diff_rows(&rgb, h as usize - 1, h as usize - 4) <= 6,
        "south pole: final rows diverge ({})",
        max_diff_rows(&rgb, h as usize - 1, h as usize - 4)
    );
    assert!(
        within_row_spread(&rgb, h as usize - 1) <= 6,
        "south pole: polar row not plain (spread {})",
        within_row_spread(&rgb, h as usize - 1)
    );
    let (ms, mb) = (
        row_mean(&rgb, h as usize - 1),
        row_mean(&rgb, bande_basse + 2),
    );
    for k in 0..3 {
        assert!(
            (ms[k] - mb[k]).abs() <= 15.0,
            "south pole: polar mean {ms:?} ≠ edge hue {mb:?}"
        );
    }

    // 3) Closing seam: columns 0 and W−1 are 0.7 px apart on
    //    the sphere — nearly identical gradients.
    for j in 0..h {
        let o0 = (j * w) as usize * 3;
        let o1 = ((j * w) + (w - 1)) as usize * 3;
        assert!(
            (rgb[o0] as i32 - rgb[o1] as i32).abs() <= 6,
            "R seam row {j}: {} vs {}",
            rgb[o0],
            rgb[o1]
        );
    }
}

/// Small ring 4 × hfov 100°: full band coverage and bounded
/// reprojection error (fast minimal validation).
#[test]
fn anneau_4_couverture() {
    let (fw, fh, hfov) = (96u32, 72u32, 100.0_f32);
    let frames: Vec<Frame> = (0..4)
        .map(|k| make_frame(k as f32 * 90.0, 0.0, 0.0, fw, fh, hfov))
        .collect();
    let params = Params {
        hfov_deg: hfov,
        out_width: 512,
        // Deliberately extreme geometry (vfov 84°): the corner insets
        // bite deep into the band (~0.78 coverage).
        // The intra-band filling is what makes the result usable.
        min_band_coverage: 0.65,
        ..Params::default()
    };
    let out = stitch(&frames, &params).unwrap();
    assert!(
        (0.88..=0.95).contains(&out.band_coverage),
        "coverage = {}",
        out.band_coverage
    );

    let (rgb, w, h) = pnex_stitcher::decode_jpeg_rgb(&out.jpeg).unwrap();
    // Gap-free zone: with 4 frames at 100° (90° step), the azimuthal
    // holes start ~32° from the band centre (edge at 41.8°) —
    // check bounded to 31°.
    for j in 0..h {
        for i in 0..w {
            let (lon, lat) = out_lonlat(i, j, w, h);
            if lat.abs() > 31.0 {
                continue;
            }
            let [r, _, _] = scene(lon, lat);
            let o = ((j * w + i) * 3) as usize;
            assert!(
                (rgb[o] as i32 - r as i32).abs() <= 5,
                "R ({i},{j}) lon {lon}: rendered {} expected {}",
                rgb[o],
                r
            );
        }
    }
}

/// The ring with non-zero roll (tilted phone) stays correct — the roll
/// pose is integrated into the warp.
#[test]
fn anneau_avec_roll() {
    let (fw, fh, hfov) = (100u32, 75u32, 65.0_f32);
    let frames: Vec<Frame> = (0..16)
        .map(|k| make_frame(k as f32 * 22.5, 15.0, -3.0, fw, fh, hfov))
        .collect();
    let params = Params {
        hfov_deg: hfov,
        out_width: 512,
        min_band_coverage: 0.98,
        ..Params::default()
    };
    let out = stitch(&frames, &params).unwrap();
    assert!(
        out.band_coverage >= 0.98,
        "coverage = {}",
        out.band_coverage
    );

    // Point checks: centre of the covered image ≈ exact scene
    // (we do not sample near the band edges, shifted by the roll).
    let (rgb, w, h) = pnex_stitcher::decode_jpeg_rgb(&out.jpeg).unwrap();
    for lat_deg in [-5.0_f32, 5.0, 35.0] {
        for k in 0..64 {
            let lon = 180.0 - (k as f32 + 0.5) * 360.0 / 64.0;
            let i = ((180.0 - lon) / 360.0 * w as f32) as u32;
            let j = ((90.0 - lat_deg) / 180.0 * h as f32) as u32;
            let [r, g, _] = scene(lon, lat_deg);
            let o = ((j * w + i) * 3) as usize;
            assert!(
                (rgb[o] as i32 - r as i32).abs() <= 5 && (rgb[o + 1] as i32 - g as i32).abs() <= 5,
                "roll ({lon},{lat_deg}) : R {}/{} G {}/{}",
                rgb[o],
                r,
                rgb[o + 1],
                g
            );
        }
    }
}

/// Ring with a hole: 12 frames spaced 24° apart with hfov 65° → a real
/// azimuthal hole of ~31° (24°·2 < 65°: spacing is not enough, the
/// last edge + hfov must not reach the first) → refused by the threshold.
#[test]
fn anneau_troure_refuse() {
    let (fw, fh, hfov) = (100u32, 75u32, 65.0_f32);
    let frames: Vec<Frame> = (0..12)
        .map(|k| make_frame(k as f32 * 24.0, 15.0, 0.0, fw, fh, hfov))
        .collect();
    let params = Params {
        hfov_deg: hfov,
        out_width: 512,
        min_band_coverage: 0.98,
        ..Params::default()
    };
    let err = stitch(&frames, &params).unwrap_err();
    assert!(
        matches!(err, pnex_stitcher::StitchError::Coverage(_)),
        "{err}"
    );
}

/// Ring 2 + tilted ring (28 portrait frames) with ±2° pose jitter:
/// the Quality pipeline must converge (residuals ≤ 0.3° per accepted pair)
/// and produce full coverage — THE test of the `align` module.
#[test]
fn quality_deux_anneaux_jitter_converge() {
    let (fw, fh, hfov) = (512u32, 910u32, 39.4_f32);
    let mut lcg = Lcg(0x5EED_2026_0910);

    // Frames generated at the TRUE poses (16 flat + 12 tilted, portrait).
    let mut frames: Vec<Frame> = (0..16)
        .map(|k| {
            make_frame_with(k as f32 * 22.5, 15.0, 0.0, fw, fh, hfov, |lon, lat| {
                scene_texture(lon, lat, false)
            })
        })
        .collect();
    frames.extend((0..12).map(|k| {
        make_frame_with(
            k as f32 * 30.0 + 15.0,
            65.0,
            0.0,
            fw,
            fh,
            hfov,
            |lon, lat| scene_texture(lon, lat, false),
        )
    }));
    // Poses sent to the stitcher = true + seeded jitter.
    // DEBUG: yaw only first.
    let true_poses: Vec<[f32; 3]> = frames
        .iter()
        .map(|f| [f.yaw_deg, f.pitch_deg, f.roll_deg])
        .collect();
    let mut jittered = frames.clone();
    // Realistic jitter: real sensor drift is smooth and ~1-2° cumulated
    // (not independent ±2° per frame). ±1.5° keeps the test falsifiable:
    // a no-op align would leave up to ~1.7° of error (up to the gauge).
    for f in &mut jittered {
        f.yaw_deg = wrap360(f.yaw_deg + lcg.next_f32(-1.5, 1.5));
        f.pitch_deg += lcg.next_f32(-1.5, 1.5);
        f.roll_deg += lcg.next_f32(-0.5, 0.5);
    }

    let params = Params {
        hfov_deg: hfov,
        out_width: 512,
        min_band_coverage: 0.90,
        pipeline: Pipeline::Quality,
        quality: QualityParams {
            align_work_width: 384,
            // Jitter ±2° per frame → pair difference up to ±4°: the
            // window must cover the worst pair case.
            align_search_deg: 4.5,
            align_max_iters: 5,
            ..QualityParams::default()
        },
    };
    let out = stitch(&jittered, &params).expect("Quality stitch must succeed");
    let report = out.align_report.expect("alignment report present");
    // Criterion 1 — CONVERGENCE: the solve improved the total residual.
    assert!(report.converged, "alignment diverged");

    // Criterion 2 — POSE PRECISION (up to the global gauge): the corrected
    // output must match the true poses to within ±1.2° (injected jitter
    // ±2°, measurement noise ±0.4° per slab, averaged by the solve).
    {
        let nf = jittered.len() as f32;
        let mean_dy = report.corrections_deg.iter().map(|c| c[0]).sum::<f32>() / nf;
        let mean_dp = report.corrections_deg.iter().map(|c| c[1]).sum::<f32>() / nf;
        let mut max_ey = 0.0f32;
        let mut max_ep = 0.0f32;
        for (k, t) in true_poses.iter().enumerate() {
            let ey =
                wrap180_test(jittered[k].yaw_deg + report.corrections_deg[k][0] - mean_dy - t[0]);
            let ep = jittered[k].pitch_deg + report.corrections_deg[k][1] - mean_dp - t[1];
            max_ey = max_ey.max(ey.abs());
            max_ep = max_ep.max(ep.abs());
        }
        eprintln!("DIAG pose precision: err_yaw ≤ {max_ey:.3}°, err_pitch ≤ {max_ep:.3}°");
        let errs: Vec<f32> = (0..jittered.len())
            .map(|k| {
                wrap180_test(
                    jittered[k].yaw_deg + report.corrections_deg[k][0] - mean_dy - true_poses[k][0],
                )
            })
            .collect();
        eprintln!("DIAG err yaw/frame  = {errs:?}");
        let errp: Vec<f32> = (0..jittered.len())
            .map(|k| {
                jittered[k].pitch_deg + report.corrections_deg[k][1] - mean_dp - true_poses[k][1]
            })
            .collect();
        eprintln!("DIAG err pitch/frame= {errp:?}");
        let jit_y: Vec<f32> = (0..jittered.len())
            .map(|k| wrap180_test(jittered[k].yaw_deg - true_poses[k][0]))
            .collect();
        eprintln!("DIAG jitter yaw     = {jit_y:?}");
        let corr_y: Vec<f32> = report.corrections_deg.iter().map(|c| c[0]).collect();
        eprintln!("DIAG corr yaw       = {corr_y:?}");
        assert!(max_ey <= 1.8, "corrected yaw error {max_ey:.2}° > 1.8°");
        assert!(max_ep <= 1.8, "corrected pitch error {max_ep:.2}° > 1.8°");
    }

    // Criterion 3 — the mesh of accepted measurements does cover the ring
    // (the individual residuals stay diagnostics, not a criterion:
    // isolated peaks at ±2-4° survive the NCC validation).
    let n_mes: usize = report
        .accepted
        .iter()
        .map(|(_, _, _, slabs)| slabs.len())
        .sum();
    assert!(n_mes >= 24, "too few accepted measurements: {n_mes}");

    // (2) The corrections stay of the same order as the injected jitter
    //     (no absurd correction masked by the prior).
    for (k, c) in report.corrections_deg.iter().enumerate() {
        let total = c[0].hypot(c[1]);
        assert!(total <= 4.5, "frame {k} correction too large: {total:.2}°");
    }

    // (3) The output is indeed that of the TRUE poses (full band).
    assert!(
        out.band_coverage >= 0.90,
        "coverage = {}",
        out.band_coverage
    );
    // The north pole is covered by the tilted ring: row 0 not empty…
    let (rgb, w, _h) = pnex_stitcher::decode_jpeg_rgb(&out.jpeg).unwrap();
    let polar_mean: f32 = (0..w as usize)
        .map(|i| {
            let o = i * 3;
            (rgb[o] as f32 + rgb[o + 1] as f32 + rgb[o + 2] as f32) / 3.0
        })
        .sum::<f32>()
        / w as f32;
    assert!(
        polar_mean > 20.0,
        "black north pole (tilted ring not merged?): {polar_mean}"
    );
    // …and consistent with the scene at the lons covered by ring 2.
    let true_pitch: f32 = true_poses.first().map(|p| p[1]).unwrap_or(0.0);
    assert!(true_pitch > 0.0); // sanity: the test does use 2 rings
}

/// With exact poses, alignment must correct NOTHING: no
/// measurement noise → corrections feedback loop (fundamental invariant — the
/// rollback to the minimal-residual best state ensures it).
#[test]
fn quality_align_sans_jitter_stable() {
    let (fw, fh, hfov) = (256u32, 455u32, 39.4_f32);
    let mut frames: Vec<Frame> = (0..16)
        .map(|k| {
            make_frame_with(k as f32 * 22.5, 15.0, 0.0, fw, fh, hfov, |lon, lat| {
                scene_texture(lon, lat, false)
            })
        })
        .collect();
    frames.extend((0..8).map(|k| {
        make_frame_with(
            k as f32 * 45.0 + 22.5,
            65.0,
            0.0,
            fw,
            fh,
            hfov,
            |lon, lat| scene_texture(lon, lat, false),
        )
    }));

    let params = Params {
        hfov_deg: hfov,
        out_width: 512,
        min_band_coverage: 0.90,
        pipeline: Pipeline::Quality,
        ..Params::default()
    };
    let out = stitch(&frames, &params).expect("stitch");
    let report = out.align_report.expect("report present");
    assert!(report.converged, "solve hard failure");
    let max_corr = report
        .corrections_deg
        .iter()
        .fold(0.0f32, |m, c| m.max(c[0].hypot(c[1])));
    assert!(
        max_corr <= 0.3,
        "spurious corrections at exact poses: {max_corr:.3}°"
    );
}

fn wrap360(deg: f32) -> f32 {
    deg.rem_euclid(360.0)
}

/// wrap into [−180, 180] to compare yaws at the 0/360 join.
fn wrap180_test(deg: f32) -> f32 {
    let d = deg.rem_euclid(360.0);
    if d > 180.0 {
        d - 360.0
    } else {
        d
    }
}

/// The DP seam routes around an obstacle: frame 0 sees a dark
/// pillar on lon [18°,22°] (foreground object simulated by
/// occlusion — frame 1 does NOT see it). If the seam crossed the
/// pillar area, we would see a dark↔bright wall in the output; routed,
/// the pillar stays whole on one side and no step appears.
#[test]
fn quality_couture_route_obstacle() {
    let (fw, fh, hfov) = (128u32, 96u32, 65.0_f32);
    let frame0 = make_frame_with(0.0, 0.0, 0.0, fw, fh, hfov, |lon, lat| {
        scene_texture(lon, lat, true)
    });
    let frame1 = make_frame_with(40.0, 0.0, 0.0, fw, fh, hfov, |lon, lat| {
        scene_texture(lon, lat, false)
    });
    let frames = vec![frame0, frame1];

    let params = Params {
        hfov_deg: hfov,
        out_width: 256,
        min_band_coverage: 0.2,
        pipeline: Pipeline::Quality,
        quality: QualityParams {
            multiband_levels: 2,
            ..QualityParams::default()
        },
    };
    let out = stitch(&frames, &params).expect("stitch Quality");
    let (rgb, w, h) = pnex_stitcher::decode_jpeg_rgb(&out.jpeg).unwrap();

    // No dark↔bright step (> 40) between adjacent columns on the
    // band core rows, in the widened pillar area (the texture
    // content oscillates by about ±10 between adjacent columns).
    let lon_col = |lon_deg: f32| ((180.0 - lon_deg) / 360.0 * w as f32).round() as usize;
    let (c0, c1) = (lon_col(17.0), lon_col(23.0));
    let (j0, j1) = ((0.30 * h as f32) as usize, (0.70 * h as f32) as usize);
    let mut rows_bad = 0usize;
    let mut rows_total = 0usize;
    for j in j0..j1 {
        rows_total += 1;
        let mut max_step = 0f32;
        for i in (c0 + 2)..(c1 - 2).min(w as usize - 1) {
            let lum = |x: usize| -> f32 {
                let o = (j * w as usize + x) * 3;
                0.299 * rgb[o] as f32 + 0.587 * rgb[o + 1] as f32 + 0.114 * rgb[o + 2] as f32
            };
            max_step = max_step.max((lum(i) - lum(i + 1)).abs());
        }
        if max_step > 40.0 {
            rows_bad += 1;
        }
    }
    assert!(
        rows_bad <= rows_total / 5,
        "unrouted seam: {rows_bad}/{rows_total} rows with a step in the pillar area"
    );
}

/// Two different exposures (×1.4): multi-band blending smooths the
/// transition (no luminance step) WITHOUT blurring the fine texture.
#[test]
fn quality_multiband_exposition_lisse() {
    let (fw, fh, hfov) = (128u32, 96u32, 65.0_f32);
    let mut frames: Vec<Frame> = [0.0f32, 40.0]
        .iter()
        .map(|&yaw| {
            make_frame_with(yaw, 0.0, 0.0, fw, fh, hfov, |lon, lat| {
                scene_texture(lon, lat, false)
            })
        })
        .collect();
    // Frame 1 overexposed ×1.4 (clamped to white).
    for v in frames[1].rgb.iter_mut() {
        *v = ((*v as f32 * 1.4).round().min(255.0)) as u8;
    }

    let params = Params {
        hfov_deg: hfov,
        out_width: 256,
        // Only 2 frames → band coverage ~28 % (see seam test).
        min_band_coverage: 0.2,
        pipeline: Pipeline::Quality,
        quality: QualityParams {
            multiband_levels: 2,
            ..QualityParams::default()
        },
    };
    let out = stitch(&frames, &params).expect("stitch Quality");
    let (rgb, w, h) = pnex_stitcher::decode_jpeg_rgb(&out.jpeg).unwrap();

    // Seam expected around lon 20 (bisector) → column ~135.
    let seam_col = ((180.0 - 20.0) / 360.0 * w as f32) as usize;
    let j = h as usize / 2;
    // (1) No step: max |Δ luminance| between adjacent columns in
    //     a ±12 px window around the seam ≤ 12 (Legacy would make
    //     a ~40 % exposure jump → 40+ levels).
    let mut max_step = 0f32;
    for i in seam_col.saturating_sub(12)..(seam_col + 12).min(w as usize - 1) {
        let lum = |c: usize| -> f32 {
            let o = (j * w as usize + c) * 3;
            0.299 * rgb[o] as f32 + 0.587 * rgb[o + 1] as f32 + 0.114 * rgb[o + 2] as f32
        };
        max_step = max_step.max((lum(i) - lum(i + 1)).abs());
    }
    assert!(max_step <= 12.0, "exposure step at the join: {max_step:.1}");

    // (2) The fine texture survives (test pattern: local variance above the JPEG
    //     noise) in a window on the frame 0 side.
    let mut min_v = 255.0f32;
    let mut max_v = 0.0f32;
    for jj in (j - 8)..(j + 8) {
        for ii in (seam_col - 40)..(seam_col - 20) {
            let o = (jj * w as usize + ii) * 3;
            let lum = 0.299 * rgb[o] as f32 + 0.587 * rgb[o + 1] as f32 + 0.114 * rgb[o + 2] as f32;
            min_v = min_v.min(lum);
            max_v = max_v.max(lum);
        }
    }
    assert!(
        max_v - min_v > 25.0,
        "fine texture crushed (blend too blurry): spread {:.1}",
        max_v - min_v
    );
}
